using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.InputSystem;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class BNAudit {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B2_DomeNetwork/";static string O=>R+"/Docs/Review/2026-11-10_B2_DomeNetwork/";
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved B2 edit required");var before=JArray.Parse(File.ReadAllText(H+"before.json"));var missing=new List<string>();var moved=new List<string>();var inactive=new List<string>();foreach(var b in before){if(!GlobalObjectId.TryParse((string)b["id"],out var gid))throw new Exception("Bad baseline ID");var t=GlobalObjectId.GlobalObjectIdentifierToObjectSlow(gid) as Transform;if(!t){missing.Add((string)b["name"]);continue;}var v=b["position"];var p=new Vector3((float)v[0],(float)v[1],(float)v[2]);if(Vector3.Distance(t.position,p)>.001f)moved.Add(t.name);if((bool)b["active"]!=t.gameObject.activeSelf)inactive.Add(t.name);}
 var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var lights=s.GetRootGameObjects().Where(g=>g.name.StartsWith("B2_")).SelectMany(g=>g.GetComponentsInChildren<Light>()).ToArray();var plan=JObject.Parse(File.ReadAllText(H+"layout.json"));var mismatches=new List<string>();foreach(var p in plan["placements"]){var t=all.SingleOrDefault(t=>t.name==(string)p["name"]);if(!t){mismatches.Add((string)p["name"]+" missing");continue;}var v=p["position"];if(Vector3.Distance(t.localPosition,new Vector3((float)v[0],(float)v[1],(float)v[2]))>.001f||Mathf.Abs(Mathf.DeltaAngle(t.localEulerAngles.y,(float)p["yaw"]))>.1f)mismatches.Add(t.name);}
 var root=GameObject.Find("B2_DomeServiceNetwork");var renderers=root.GetComponentsInChildren<MeshRenderer>();var bad=renderers.Where(r=>!r.GetComponent<MeshFilter>()||!r.GetComponent<MeshFilter>().sharedMesh||r.sharedMaterials.Any(m=>!m||!m.shader||m.shader.name.Contains("Error"))).Select(r=>r.name).ToArray();var overlaps=new List<object>();var props=root.transform.Find("ProcessIslandsAndMaintenance").GetComponentsInChildren<BoxCollider>();foreach(var p in props){var hits=Physics.OverlapBox(p.transform.TransformPoint(p.center),Vector3.Scale(p.size,p.transform.lossyScale)*.49f,p.transform.rotation,~0,QueryTriggerInteraction.Ignore).Where(c=>c!=p&&!c.transform.IsChildOf(p.transform)&&!c.name.Contains("Floor")&&!c.name.Contains("WalkCollision")).ToArray();if(hits.Length>0)overlaps.Add(new{name=p.name,hits=hits.Select(c=>c.name).Distinct().ToArray()});}
 var result=new{baseline=before.Count,missing,moved,activeChanges=inactive,placements=plan["placements"].Count(),placementMismatches=mismatches,badMeshesMaterials=bad,activeLights=lights.Length,whiteLights=lights.Count(l=>l.color.g>.55f&&l.color.b>.55f),newLods=root.GetComponentsInChildren<LODGroup>().Length,overlaps,mouse=Mouse.current.enabled,keyboard=Keyboard.current.enabled,saved=!s.isDirty};File.WriteAllText(O+"audit.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
